{{ config(
            materialized='table',
                post_hook={
                    "sql": "WITH google_hourly AS ( SELECT DATE, CAMPAIGN_NAME, CAMPAIGN_ID, ANY_VALUE(AD_NAME) AS AD_NAME, ANY_VALUE(AD_ID) AS AD_ID, ANY_VALUE(ADSET_NAME) AS ADSET_NAME, SUM(SPEND) AS SPEND, SUM(IMPRESSIONS) AS IMPRESSIONS, SUM(CLICKS) AS CLICKS FROM `beastlife-wh-474411.maplemonk.beastlife_hourly_MARKETING_CONSOLIDATED` WHERE ACCOUNT_NAME = \'GOOGLE ADS\' GROUP BY DATE, CAMPAIGN_NAME, CAMPAIGN_ID ), shopify_hourly AS ( SELECT Order_Date, utm_campaign, SUM( CASE WHEN Order_Date >= DATE \'2025-09-22\' THEN (selling_price / 1.06) * 0.90 ELSE (selling_price / 1.18) * 0.90 END ) AS NSV, SUM(selling_price) * 0.90 AS gross_sales, SUM(selling_price) AS sell, COUNT(DISTINCT order_id) AS orders, SUM(quantity) * 0.90 AS quantity, COUNT(DISTINCT CASE WHEN new_customer_flag = \'Repeat\' THEN order_id END) * 0.90 AS repeat_orders, COUNT(DISTINCT CASE WHEN new_customer_flag = \'New\' THEN order_id END) * 0.90 AS new_orders, SUM(CASE WHEN new_customer_flag = \'New\' THEN selling_price * 0.90 ELSE 0 END) AS new_customer_sales, SUM(CASE WHEN new_customer_flag = \'Repeat\' THEN selling_price * 0.90 ELSE 0 END) AS repeat_customer_sales, SUM(IF(cod_pp_flag = \'COD\', selling_price * 0.90, 0)) AS cod_sales, SUM(IF(cod_pp_flag = \'Prepaid\', selling_price * 0.90, 0)) AS prepaid_sales, SUM(IF(cod_pp_flag = \'Partial Paid\', selling_price * 0.90, 0)) AS partial_paid_sales, COUNT(DISTINCT CASE WHEN cod_pp_flag = \'COD\' THEN order_id END) * 0.90 AS cod_orders, COUNT(DISTINCT CASE WHEN cod_pp_flag = \'Prepaid\' THEN order_id END) * 0.90 AS prepaid_orders, COUNT(DISTINCT CASE WHEN cod_pp_flag = \'Partial Paid\' THEN order_id END) * 0.90 AS partial_paid_orders FROM `beastlife-wh-474411.maplemonk.Hourly_D2C_master` WHERE channel IN (\'GOOGLE\',\'GOOGLE_ADS\') AND order_status = \'SHOPIFY_PROCESSED\' GROUP BY 1,2 ), google_live AS ( SELECT COALESCE(g.DATE, s.Order_Date) AS DATE, g.CAMPAIGN_NAME, g.AD_NAME, g.ADSET_NAME, SUM(g.SPEND) AS total_spend, SUM(g.IMPRESSIONS) AS total_impressions, SUM(g.CLICKS) AS total_clicks, COALESCE(SUM(s.gross_sales),0) AS total_gross_sales, COALESCE(SUM(s.sell),0) AS total_sell, COALESCE(SUM(s.orders),0) AS total_orders, COALESCE(SUM(s.repeat_orders),0) AS total_repeat_orders, COALESCE(SUM(s.new_orders),0) AS total_new_orders, COALESCE(SUM(s.new_customer_sales),0) AS total_new_customer_sales, COALESCE(SUM(s.repeat_customer_sales),0) AS total_repeat_customer_sales, COALESCE(SUM(s.cod_sales),0) AS total_cod_sales, COALESCE(SUM(s.prepaid_sales),0) AS total_prepaid_sales, COALESCE(SUM(s.partial_paid_sales),0) AS total_partial_paid_sales, COALESCE(SUM(s.cod_orders),0) AS total_cod_orders, COALESCE(SUM(s.prepaid_orders),0) AS total_prepaid_orders, COALESCE(SUM(s.partial_paid_orders),0) AS total_partial_paid_orders, COALESCE(SUM(s.quantity),0) AS total_quantity FROM google_hourly g FULL OUTER JOIN shopify_hourly s ON g.CAMPAIGN_ID = s.utm_campaign AND g.DATE = s.Order_Date WHERE g.date = CURRENT_DATE() GROUP BY 1,2,3,4 ), google_master AS ( SELECT DATE, CAMPAIGN_NAME, CAMPAIGN_ID, ANY_VALUE(AD_NAME) AS AD_NAME, ANY_VALUE(AD_ID) AS AD_ID, ANY_VALUE(ADSET_NAME) AS ADSET_NAME, SUM(SPEND) AS SPEND, SUM(IMPRESSIONS) AS IMPRESSIONS, SUM(CLICKS) AS CLICKS FROM `beastlife-wh-474411.maplemonk.beastlife_wh_474411_MARKETING_CONSOLIDATED` WHERE ACCOUNT_NAME = \'GOOGLE ADS\' GROUP BY DATE, CAMPAIGN_NAME, CAMPAIGN_ID ), shopify_master AS ( SELECT Order_Date, utm_campaign, SUM( CASE WHEN Order_Date >= DATE \'2025-09-22\' THEN (selling_price / 1.06) * 0.90 ELSE (selling_price / 1.18) * 0.90 END ) AS NSV, SUM(selling_price) * 0.90 AS gross_sales, SUM(selling_price) AS sell, COUNT(DISTINCT order_id) AS orders, SUM(quantity) * 0.90 AS quantity, COUNT(DISTINCT CASE WHEN new_customer_flag = \'Repeat\' THEN order_id END) * 0.90 AS repeat_orders, COUNT(DISTINCT CASE WHEN new_customer_flag = \'New\' THEN order_id END) * 0.90 AS new_orders, SUM(CASE WHEN new_customer_flag = \'New\' THEN selling_price * 0.90 ELSE 0 END) AS new_customer_sales, SUM(CASE WHEN new_customer_flag = \'Repeat\' THEN selling_price * 0.90 ELSE 0 END) AS repeat_customer_sales, SUM(IF(cod_pp_flag = \'COD\', selling_price * 0.90, 0)) AS cod_sales, SUM(IF(cod_pp_flag = \'Prepaid\', selling_price * 0.90, 0)) AS prepaid_sales, SUM(IF(cod_pp_flag = \'Partial Paid\', selling_price * 0.90, 0)) AS partial_paid_sales, COUNT(DISTINCT CASE WHEN cod_pp_flag = \'COD\' THEN order_id END) * 0.90 AS cod_orders, COUNT(DISTINCT CASE WHEN cod_pp_flag = \'Prepaid\' THEN order_id END) * 0.90 AS prepaid_orders, COUNT(DISTINCT CASE WHEN cod_pp_flag = \'Partial Paid\' THEN order_id END) * 0.90 AS partial_paid_orders FROM `beastlife-wh-474411.maplemonk.D2C_master` WHERE channel IN (\'GOOGLE\',\'GOOGLE_ADS\') AND order_status = \'SHOPIFY_PROCESSED\' GROUP BY 1,2 ), google_old AS ( SELECT COALESCE(g.DATE, s.Order_Date) AS DATE, g.CAMPAIGN_NAME, g.AD_NAME, g.ADSET_NAME, SUM(g.SPEND) AS total_spend, SUM(g.IMPRESSIONS) AS total_impressions, SUM(g.CLICKS) AS total_clicks, COALESCE(SUM(s.gross_sales),0) AS total_gross_sales, COALESCE(SUM(s.sell),0) AS total_sell, COALESCE(SUM(s.orders),0) AS total_orders, COALESCE(SUM(s.repeat_orders),0) AS total_repeat_orders, COALESCE(SUM(s.new_orders),0) AS total_new_orders, COALESCE(SUM(s.new_customer_sales),0) AS total_new_customer_sales, COALESCE(SUM(s.repeat_customer_sales),0) AS total_repeat_customer_sales, COALESCE(SUM(s.cod_sales),0) AS total_cod_sales, COALESCE(SUM(s.prepaid_sales),0) AS total_prepaid_sales, COALESCE(SUM(s.partial_paid_sales),0) AS total_partial_paid_sales, COALESCE(SUM(s.cod_orders),0) AS total_cod_orders, COALESCE(SUM(s.prepaid_orders),0) AS total_prepaid_orders, COALESCE(SUM(s.partial_paid_orders),0) AS total_partial_paid_orders, COALESCE(SUM(s.quantity),0) AS total_quantity FROM google_master g FULL OUTER JOIN shopify_master s ON g.CAMPAIGN_ID = s.utm_campaign AND g.DATE = s.Order_Date WHERE g.DATE < CURRENT_DATE() GROUP BY 1,2,3,4 ), calendar AS ( SELECT PARSE_DATE(\'%Y-%m-%d\', event_date) AS event_date, Event, sub_event, FORMAT_DATE(\'%Y%m%d\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DateAsInteger, FORMAT_DATE(\'%d\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DateNumber, EXTRACT(YEAR FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS Year, FORMAT_DATE(\'%m\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS MonthNumber, FORMAT_DATE(\'%Y/%m\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS YearMonthNumber, FORMAT_DATE(\'%Y/%b\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS YearMonthShort, FORMAT_DATE(\'%b\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS MonthNameShort, FORMAT_DATE(\'%B\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS MonthNameLong, EXTRACT(DAYOFWEEK FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DayOfWeekNumber, FORMAT_DATE(\'%A\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DayOfWeek, FORMAT_DATE(\'%a\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DayOfWeekShort, CONCAT(\'Q\', CAST(EXTRACT(QUARTER FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS STRING)) AS Quarter, CONCAT(FORMAT_DATE(\'%Y\', PARSE_DATE(\'%Y-%m-%d\', event_date)), \'/Q\', CAST(EXTRACT(QUARTER FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS STRING)) AS YearQuarter, CASE WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 1 AND 7 THEN \'W1\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 8 AND 14 THEN \'W2\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 15 AND 21 THEN \'W3\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 22 AND 28 THEN \'W4\' ELSE \'W5\' END AS WeekPeriod FROM `beastlife-wh-474411.maplemonk.beastlife_db_Calender` ) SELECT * FROM ( SELECT * FROM google_live UNION ALL SELECT * FROM google_old ) base LEFT JOIN calendar ON base.DATE = calendar.event_date ORDER BY total_spend DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
